    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long ev = 0, od = -1000000000000000000LL;
    for (long long x : a) {
        long long newEv = max(ev, od - x);
        long long newOd = max(od, ev + x);
        ev = newEv;
        od = newOd;
    }
    cout << max(ev, od) << "\n";

